import csv, math, os, statistics
filename = 'concrete_compressive_strength.csv'
if not os.path.exists(filename):
    print('File not found')
else:
    with open(filename, newline='') as f:
        reader = csv.DictReader(f)
        values = []
        for row in reader:
            val = row.get('Fine Aggregate')
            if val is None:
                continue
            try:
                values.append(float(val))
            except ValueError:
                pass
    if not values:
        print('No values')
    else:
        mean = sum(values)/len(values)
        # sample standard deviation (ddof=1)
        if len(values) > 1:
            variance = sum((x-mean)**2 for x in values)/(len(values)-1)
            stdev = math.sqrt(variance)
        else:
            stdev = float('nan')
        print('Mean:', mean)
        print('Sample stdev:', stdev)
        # population std
        pop_variance = sum((x-mean)**2 for x in values)/len(values)
        pop_std = math.sqrt(pop_variance)
        print('Population std:', pop_std)

