    # Check column AH exists
    if 'AH' not in df.columns:
        print('Column AH not found, columns:', df.columns.tolist())
    else:
        # Convert to numeric, coerce errors
        series = pd.to_numeric(df['AH'], errors='coerce')
        # Drop NaN
        series = series.dropna()
        median_val = series.median()
        print('Median AH:', median_val)
else:
    # Use csv module list
    values = []
    for row in rows:
        val = row.get('AH')
        if val is None:
            continue
        try:
            v = float(val)
            values.append(v)
        except:
            continue
    if not values:
        print('No numeric values')
    else:
        values.sort()
        n = len(values)
        if n % 2 == 1:
            median_val = values[n//2]
        else:
            median_val = (values[n//2 - 1] + values[n//2]) / 2
        print('Median AH (csv):', median_val)

